/**
 * Matches any value except `null` and `undefined`, mirroring the semantics of
 * vitest's `expect.anything()`. In particular, this means a missing header,
 * query parameter or body does not match.
 * @public
 */
export declare function anyValue(): AsymmetricMatcher;

/**
 * Matches an array that contains at least the specified items (in any order).
 * @public
 */
export declare function arrayContaining(expected: unknown[]): AsymmetricMatcher;

/**
 * Protocol interface for asymmetric matching, compatible with vitest/Jest.
 * @public
 */
export declare interface AsymmetricMatcher {
  asymmetricMatch(value: unknown): boolean;
}

/**
 * Matches a request body against exact bytes. The actual value must be a
 * `Uint8Array` (which is how the mock records binary and streamed bodies) with
 * identical bytes. Accepts a `Uint8Array` or `ArrayBuffer` as the expected value.
 * @public
 */
export declare function bodyBytes(
  expected: Uint8Array | ArrayBuffer,
): AsymmetricMatcher;

/**
 * Create a mock fetch instance for testing with `createRequester`.
 *
 * @example
 * ```ts
 * const mock = createMockFetch()
 * mock.on('GET', '/api/docs').respond({ status: 200, body: { items: [] } })
 *
 * const request = createRequester({
 *   base: 'https://api.example.com',
 *   fetch: mock.fetch,
 * })
 *
 * const res = await request({ url: '/api/docs', as: 'json' })
 * ```
 *
 * @public
 */
export declare function createMockFetch(): MockFetch;

/**
 * A single field-level difference between expected and actual values.
 * @internal
 */
declare interface Diff {
  path: string;
  expected: unknown;
  actual: unknown;
}

/**
 * Valid body types for fetch requests.
 *
 * Includes `Uint8Array` since the standard `fetch` accepts typed-array
 * request bodies. It is pinned to `Uint8Array<ArrayBuffer>` (rather than the
 * abstract `ArrayBufferView` or the default `Uint8Array<ArrayBufferLike>`) to
 * stay assignable to the platform `BodyInit` across the DOM and Node lib
 * definitions, which keeps `FetchFunction` compatible with the runtime
 * `fetch`. Widening further breaks that compatibility.
 *
 * @public
 */
declare type FetchBody =
  | string
  | ArrayBuffer
  | Uint8Array<ArrayBuffer>
  | Blob
  | FormData
  | URLSearchParams
  | ReadableStream;

/**
 * A function that performs an HTTP fetch. Must conform to the standard
 * `fetch()` signature but only needs to return a `FetchResponse`.
 *
 * @param input - The URL to fetch.
 * @param init - Optional request init options.
 * @returns A promise resolving to the response.
 *
 * @public
 */
declare type FetchFunction = (
  input: string,
  init?: FetchInit,
) => Promise<FetchResponse>;

/**
 * Accepted header formats — tuple pairs, a plain record, or a `Headers` instance.
 *
 * @public
 */
declare type FetchHeaders =
  [string, string][] | Record<string, string> | Headers;

/**
 * Init options passed to a {@link FetchFunction}.
 *
 * This is a minimal subset of the standard `RequestInit` so the library
 * doesn't depend on the full DOM lib.
 *
 * @public
 */
declare interface FetchInit {
  /** HTTP method (GET, POST, PUT, etc.). */
  method?: string;
  /** Request headers. */
  headers?: FetchHeaders;
  /** Request body. */
  body?: FetchBody | null;
  /** Abort signal for cancellation. */
  signal?: AbortSignal;
  /**
   * Redirect handling strategy.
   *
   * ⚠️ In browsers, `'manual'` yields an opaque-redirect response (status `0`,
   * empty headers) per the Fetch spec — you cannot read the status or headers
   * (e.g. `location`) of the 3xx response. Reading them throws nothing and warns
   * nothing: `headers.get()` returns `null` and iteration is empty. Detect it via
   * `status === 0`. Non-browser runtimes (Node.js, Bun, Deno, edge runtimes,
   * workers) return the real 3xx response, so its status and headers are readable.
   */
  redirect?: "error" | "follow" | "manual";
  /** Credentials mode (browser-only — some runtimes crash if set). */
  credentials?: "include" | "omit" | "same-origin";
}

/**
 * Response object returned by a {@link FetchFunction}.
 *
 * A minimal subset of the standard `Response` — just the properties
 * get-it actually reads.
 *
 * @public
 */
declare interface FetchResponse {
  /** Whether the response status is in the 200–299 range. */
  ok: boolean;
  /** HTTP status code. */
  status: number;
  /** HTTP status text (e.g. "OK", "Not Found"). */
  statusText: string;
  /** Response headers. */
  headers: Headers;
  /** The final URL after any redirects. */
  url: string;
  /** Whether the response was the result of a redirect. */
  redirected: boolean;
  /** Readable stream of the response body, or `null` if empty. */
  body: ReadableStream<Uint8Array> | null;
  /** Reads the entire body as a string. */
  text(): Promise<string>;
  /** Reads the entire body as an ArrayBuffer. */
  arrayBuffer(): Promise<ArrayBuffer>;
}

/**
 * Description of a registered mock for error reporting.
 * @public
 */
export declare interface MockDescription {
  description: string;
  responsesRemaining: number;
}

/**
 * The mock fetch instance returned by `createMockFetch()`.
 * @public
 */
export declare interface MockFetch {
  fetch: FetchFunction;
  on(
    method: string,
    url: string | ((url: string) => boolean),
    options?: MockMatchOptions,
  ): MockHandler;
  onAny(
    url: string | ((url: string) => boolean),
    options?: MockMatchOptions,
  ): MockHandler;
  getRequests(): ReadonlyArray<RecordedRequest>;
  assertAllConsumed(): void;
  clear(): void;
  scope(baseUrl: string): MockScope;
}

/**
 * Error thrown when no registered mock matches a request.
 * Includes the closest mock (if any) with a diff of differences.
 *
 * @public
 */
export declare class MockFetchError extends Error {
  method: string;
  url: string;
  query: Record<string, string>;
  body: unknown;
  constructor(
    method: string,
    url: string,
    query: Record<string, string>,
    body: unknown,
    diffs: Diff[],
    allMocks: MockDescription[],
    closestDescription?: string,
  );
}

/**
 * Handler builder returned by `.on()` / `.onAny()`.
 * @public
 */
export declare interface MockHandler {
  respond(def: MockResponseDef): MockHandler;
  respondPersist(def: MockResponseDef): MockHandler;
  /**
   * Reject the matched request with a transport-level error (mirrors how a real
   * `fetch()` rejects on a failed connection), instead of resolving to a
   * `Response`. Accepts an `Error` instance, or a factory invoked once per
   * consumption so each rejection gets a fresh instance. The value is thrown
   * unmodified, preserving `name`/`message`/`cause`.
   */
  respondWithError(error: Error | (() => Error)): MockHandler;
  /** Like {@link respondWithError}, but rejects on every matching request. */
  respondWithErrorPersist(error: Error | (() => Error)): MockHandler;
}

/**
 * Options for matching a request beyond method and URL.
 * @public
 */
export declare interface MockMatchOptions {
  query?: Record<string, string | number | boolean> | AsymmetricMatcher;
  body?: unknown;
  headers?: Record<string, string | AsymmetricMatcher> | AsymmetricMatcher;
}

/**
 * Definition for a mock response.
 * @public
 */
export declare interface MockResponseDef {
  status?: number;
  statusText?: string;
  body?: unknown;
  headers?: Record<string, string>;
  /**
   * Delay in milliseconds before the response resolves, simulating server
   * response time. The request is treated as sent immediately; this is how
   * long the "server" takes to respond. Values <= 0 resolve immediately.
   */
  delay?: number;
}

/**
 * A scoped view of the mock, constraining handlers and requests to a specific origin.
 * @public
 */
export declare interface MockScope {
  on(
    method: string,
    url: string | ((url: string) => boolean),
    options?: MockMatchOptions,
  ): MockHandler;
  onAny(
    url: string | ((url: string) => boolean),
    options?: MockMatchOptions,
  ): MockHandler;
  getRequests(): ReadonlyArray<RecordedRequest>;
  assertAllConsumed(): void;
}

/**
 * Matches an object that contains at least the specified keys with matching values.
 * Extra keys on the actual value are ignored.
 * @public
 */
export declare function objectContaining(
  expected: Record<string, unknown>,
): AsymmetricMatcher;

/**
 * Matches a query object that contains at least the specified keys with matching
 * values. Expected values are coerced to strings before comparison, since query
 * parameters are always strings. An array expected value matches a multi-value
 * param (an array actual) that contains each expected value. Extra keys on the
 * actual value are ignored.
 * @public
 */
export declare function queryContaining(
  expected: Record<
    string,
    string | number | boolean | Array<string | number | boolean>
  >,
): AsymmetricMatcher;

/**
 * A recorded request captured by the mock.
 * @public
 */
export declare interface RecordedRequest {
  method: string;
  url: string;
  fullUrl: string;
  query: Record<string, string>;
  headers: Headers;
  body: unknown;
  /**
   * The raw init object passed to the mock fetch call, verbatim (or `undefined`
   * if the fetch was called without one). Useful for asserting on transport-level
   * fields like `signal`, or non-standard fields forwarded by composed fetches
   * (e.g. Next.js `cache`/`next`) — reach those via narrowing (`'next' in init`).
   */
  init: FetchInit | undefined;
}

/**
 * Marker object recognized in `MockResponseDef.body`, produced by
 * {@link streamBody}. Also serves as the observability handle: a fresh
 * stream is built from the script for every consumption, and consumer
 * cancellations and request-signal aborts are aggregated on this object.
 * @public
 */
export declare class StreamBody {
  /** Number of times a consumer cancelled a stream produced from this script. */
  cancelCount: number;
  /** The reason passed to the most recent cancel, if any. */
  lastCancelReason: unknown;
  /** Number of times a request's abort signal terminated a stream produced from this script. */
  abortCount: number;
  /** The abort reason from the most recent request-signal abort, if any. */
  lastAbortReason: unknown;
  /** The validated script. @internal */
  readonly script: ReadonlyArray<StreamPart>;
  /** Use {@link streamBody} instead of constructing directly. @internal */
  constructor(parts: ReadonlyArray<StreamPart>);
}

/**
 * Declare a streaming mock response body: chunks delivered in order,
 * interleaved with timing/termination directives. Pass the result as
 * `MockResponseDef.body`. Validates the script eagerly.
 *
 * @example
 * ```ts
 * const body = streamBody('partial', streamDelay(1000), 'done')
 * mock.on('GET', '/backup').respond({status: 200, body})
 * ```
 *
 * @public
 */
export declare function streamBody(...parts: StreamPart[]): StreamBody;

/** Pause `ms` milliseconds before delivering the next part. @public */
export declare function streamDelay(ms: number): StreamDirective;

/**
 * A directive controlling timing or termination inside a {@link streamBody}
 * script. Create via {@link streamDelay}, {@link streamStall}, or
 * {@link streamError}.
 * @public
 */
export declare type StreamDirective =
  | {
      kind: "delay";
      ms: number;
    }
  | {
      kind: "stall";
    }
  | {
      kind: "error";
      error: Error;
    };

/**
 * Terminal directive: after the preceding chunks, the body stream errors
 * with `error`, simulating a connection cut mid-download.
 * @public
 */
export declare function streamError(error: Error): StreamDirective;

/**
 * One part of a {@link streamBody} script: a body chunk (string is UTF-8
 * encoded, `Uint8Array` passes through as bytes) or a {@link StreamDirective}.
 * @public
 */
export declare type StreamPart = string | Uint8Array | StreamDirective;

/**
 * Terminal directive: after the preceding chunks, the body never closes.
 * The stream ends only when the consumer cancels it or the request's
 * abort signal fires.
 * @public
 */
export declare function streamStall(): StreamDirective;

/**
 * Matches a string against a regex or substring.
 * @public
 */
export declare function stringMatching(
  pattern: RegExp | string,
): AsymmetricMatcher;

export {};
